import React from 'react';

import CommentsWidget from '@apps/Comments/components/CommentsWidget';
import Page from '@components/Page';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { getRecipeByIdAsync } from '../@services/recipes.service';
import { IFullRecipe } from '../@types/recipes.types';
import RecipeOne from '../components/RecipeOne';
import { RecipeUsagesWidget } from '../components/RecipeUsages';

interface IRecipeOnePageProps {
  id_recipe: number;
}

const RecipeOnePage: React.FC<IRecipeOnePageProps> = ({ id_recipe }) => {
  const [err, setErr] = React.useState<Error>();
  const [isLoading, setIsLoading] = React.useState(true);
  const [recipeData, setRecipeData] = React.useState<IFullRecipe>();

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const rd = await getRecipeByIdAsync(id_recipe);
        setRecipeData(rd);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_recipe]);

  if (isLoading) return <PageLoader />;

  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!recipeData) return <PohAlert variant={AlertVariant.Danger}>Has no recipeData</PohAlert>;

  return (
    <Page
      title={recipeData.name}
      description={recipeData.promo}
      keywords={recipeData.products.map((p) => p.name)}
      image={recipeData.photo}
    >
      <PohBreadcrumbs
        data={[
          { href: '/recipes', text: 'Рецепты' },
          { href: `/recipes/${id_recipe}`, text: recipeData.name, active: true },
        ]}
      />
      <PohContainer>
        <PohRow>
          <PohCol sm={{ span: 8, offset: 2 }}>
            <RecipeOne id_recipe={id_recipe} recipeData={recipeData} />
          </PohCol>
        </PohRow>
        <RecipeUsagesWidget id_recipe={id_recipe} />
        <hr />
        <CommentsWidget id_recipe={id_recipe} />
      </PohContainer>
    </Page>
  );
};

export default RecipeOnePage;
